INSERT INTO `step_algorithm` (`id`, `step_id`, `algorithm_name`, `algorithm_code`, `algorithm_order`, `ql_expression`, `input_params`, `output_param`, `description`, `status`, `create_time`) VALUES (634,15,'队伍管理能力计算','MANAGEMENT_CAPABILITY',1,'(management_staff * 1.0 / population) * 10000',NULL,'managementCapability','队伍管理能力=(本级灾害管理工作人员总数/常住人口数量)*10000',1,'2025-10-19 09:19:04');
